CREATE OR REPLACE PROCEDURE public.sp_update_child_care_event(IN p_id uuid, IN p_tenant_id uuid, IN p_event_time timestamp with time zone, IN p_diaper_condition character varying, IN p_skin_observation character varying, IN p_meal_type character varying, IN p_food_offered character varying, IN p_amount_consumed character varying, IN p_fluid_oz numeric, IN p_rest_status character varying, IN p_toileting_activity character varying, IN p_hygiene_type character varying, IN p_comfort_mood character varying, IN p_notes text, IN p_parent_visible boolean, IN p_correction_reason text, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE child_care_events     SET event_time = p_event_time,         diaper_condition = p_diaper_condition,         skin_observation = p_skin_observation,         meal_type = p_meal_type,         food_offered = p_food_offered,         amount_consumed = p_amount_consumed,         fluid_oz = p_fluid_oz,         rest_status = p_rest_status,         toileting_activity = p_toileting_activity,         hygiene_type = p_hygiene_type,         comfort_mood = p_comfort_mood,         notes = p_notes,         parent_visible = p_parent_visible,         correction_reason = p_correction_reason,         is_corrected = TRUE,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
